  /* 並べる: 先頭（選んだもの）→ 一覧 → 待っているもの。先頭から抜けるものは上へ抜けて下から戻る（逆も同じ） */
  const MOVE164 = '340ms cubic-bezier(.22,.8,.24,1)';
